appsmith.onReady(() => {
  console.log("🚀 Iniciando widget Mapa");

  // Variables globales
  let map = null;
  let currentLayer = null;

  // Función para obtener estilos según highlight_status
  function getStyle(feature) {
    const props = feature.properties || {};
    const highlightStatus = props.highlight_status || 'default';
    const styles = {
      default: {
        fillColor: '#3388ff',
        weight: 1.5,
        opacity: 0.8,
        color: '#ffffff',
        fillOpacity: 0.35
      },
      highlight_municipio: {
        fillColor: '#3b82f6',
        weight: 2.5,
        opacity: 1,
        color: '#ffffff',
        fillOpacity: 0.55
      },
      highlight_parroquia: {
        fillColor: '#ff7800',
        weight: 3,
        opacity: 1,
        color: '#ffcc00',
        fillOpacity: 0.7
      }
    };
    return styles[highlightStatus] || styles.default;
  }

  // Función para actualizar panel de información
  function updateInfoPanel(selectedMunicipio, selectedParroquia, featureCount) {
    const panel = document.getElementById('infoPanel');
    if (!panel) return;
    let text = '📍 <strong>Carabobo, Venezuela</strong>';
    if (selectedParroquia) {
      text += `<br>🏘️ Parroquia: <strong style="color:#ff7800">${selectedParroquia}</strong>`;
    } else if (selectedMunicipio) {
      text += `<br>🏛️ Municipio: <strong style="color:#3b82f6">${selectedMunicipio}</strong>`;
    } else {
      text += `<br>📌 Mostrando todas las parroquias (${featureCount})`;
    }
    panel.innerHTML = text;
  }

  // Función para inicializar el mapa
  function initMap() {
    if (map) {
      map.remove();
    }
    map = L.map('map').setView([10.180, -68.004], 10);

    // Capa base - CartoDB Voyager (más clara)
    L.tileLayer('https://{s}.basemaps.cartocdn.com/light_all/{z}/{x}/{y}{r}.png', {
      attribution: '&copy; <a href="https://www.openstreetmap.org/copyright">OSM</a> &copy; <a href="https://carto.com/attributions">CARTO</a>',
      subdomains: 'abcd',
      maxZoom: 19
    }).addTo(map);
    console.log("✅ Mapa inicializado");
  }

  // Función para cargar y renderizar los datos
  function cargarMapa() {
    try {
      console.log("🔄 Cargando mapa...");

      // Obtener valores de los widgets desde appsmith.model
      const selectedMunicipio = appsmith.model.alcaldia?.selectedOptionValue || null;
      const selectedParroquia = appsmith.model.parroquia?.selectedOptionValue || null;
      console.log("📊 Filtros - Municipio:", selectedMunicipio, "Parroquia:", selectedParroquia);

      // Obtener datos del query - Asumiendo que el query se llama "mapData"
      let geoJSONData = null;
      const queryResult = appsmith.model.mapData;
      console.log("📦 Query result:", queryResult);
      if (queryResult && queryResult.length > 0 && queryResult[0].geojson_collection) {
        geoJSONData = queryResult[0].geojson_collection;
        console.log("✅ Datos cargados correctamente");
      } else if (queryResult && queryResult.geojson_collection) {
        geoJSONData = queryResult.geojson_collection;
        console.log("✅ Datos cargados (formato alternativo)");
      } else {
        console.warn("⚠️ No se encontraron datos en appsmith.model.mapData");
        document.getElementById('loadingIndicator').style.display = 'none';
        document.getElementById('infoPanel').innerHTML = '❌ No se pudieron cargar los datos';
        return;
      }
      if (!geoJSONData || !geoJSONData.features || geoJSONData.features.length === 0) {
        console.warn("⚠️ GeoJSON vacío");
        document.getElementById('loadingIndicator').style.display = 'none';
        document.getElementById('infoPanel').innerHTML = '❌ No hay datos disponibles';
        return;
      }
      const featureCount = geoJSONData.features.length;
      console.log(`📦 GeoJSON cargado con ${featureCount} features`);
      updateInfoPanel(selectedMunicipio, selectedParroquia, featureCount);
      document.getElementById('legend').style.display = 'block';

      // Remover capa anterior
      if (currentLayer) {
        map.removeLayer(currentLayer);
      }

      // Crear nueva capa GeoJSON
      currentLayer = L.geoJSON(geoJSONData, {
        style: getStyle,
        onEachFeature: function (feature, layer) {
          const props = feature.properties || {};
          const parroquia = props.parroquia || 'Parroquia sin nombre';
          const municipio = props.municipio || 'Municipio sin nombre';

          // Tooltip
          layer.bindTooltip(`
                        <div style="font-weight:bold; color:#ff7800;">${parroquia}</div>
                        <div style="font-size:11px;">${municipio}</div>
                    `, {
            sticky: true,
            direction: 'top',
            offset: [0, -8],
            className: 'custom-tooltip'
          });

          // Popup
          layer.bindPopup(`
                        <div class="popup-title">${parroquia}</div>
                        <div class="popup-item">
                            <span class="popup-label">Municipio:</span>
                            <span class="popup-value">${municipio}</span>
                        </div>
                        <div class="popup-item">
                            <span class="popup-label">Estado:</span>
                            <span class="popup-value">Carabobo</span>
                        </div>
                    `, {
            className: 'custom-popup'
          });

          // Efectos hover
          layer.on('mouseover', function () {
            const originalStyle = getStyle(feature);
            layer.setStyle({
              fillOpacity: Math.min(originalStyle.fillOpacity + 0.2, 0.9),
              weight: originalStyle.weight + 1,
              color: '#ffff00'
            });
            layer.bringToFront();
          });
          layer.on('mouseout', function () {
            layer.setStyle(getStyle(feature));
          });
        }
      }).addTo(map);

      // Ajustar vista
      if (currentLayer.getBounds().isValid()) {
        map.fitBounds(currentLayer.getBounds(), {
          padding: [30, 30],
          maxZoom: 12
        });
      }
      document.getElementById('loadingIndicator').style.display = 'none';
      console.log("✅ Mapa renderizado exitosamente");
    } catch (error) {
      console.error("❌ Error:", error);
      document.getElementById('loadingIndicator').style.display = 'none';
      document.getElementById('infoPanel').innerHTML = `❌ Error: ${error.message}`;
    }
  }

  // Verificar que Leaflet esté cargado
  function waitForLeaflet() {
    if (typeof L !== 'undefined') {
      console.log("✅ Leaflet cargado");
      initMap();
      cargarMapa();
    } else {
      console.log("⏳ Esperando a que Leaflet se cargue...");
      setTimeout(waitForLeaflet, 200);
    }
  }

  // Iniciar cuando el DOM esté listo
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', waitForLeaflet);
  } else {
    waitForLeaflet();
  }

  // Exponer función para refrescar desde Appsmith
  window.refreshMap = function () {
    console.log("🔄 Refrescando mapa...");
    if (map) {
      cargarMapa();
    } else {
      initMap();
      cargarMapa();
    }
  };
});

